def luhn_valid(s):
    s = ''.join(c for c in s if c.isdigit())  # Supprime les espaces et les autres caractères non numériques
    if len(s) < 2:
        return False
    sum_digits = 0
    for i in range(len(s)-1, -1, -1):
        digit = int(s[i])
        if i % 2 == 0:
            digit *= 2
            if digit > 9:
                digit -= 9
        sum_digits += digit
    return sum_digits % 10 == 0
```

